INSERT INTO feature VALUES('user-operators','syntax','User-declared operators',NULL,'declined','ordinary',NULL,'Declined by #1111: the `op` declaration, which parsed a fixity, a precedence and a spelling and was refused at the root, named no function a spelling calls and folded nothing into the grammar, so the `operator_declaration` rule is deleted. User-declared operators return with a designed keyword, a binding from each spelling to the function it calls, and a measured run-time grammar (#3559).',NULL,NULL,NULL,'#3559');
